1	import {
2	  openSync,
3	  closeSync,
4	  readSync,
5	  writeSync,
6	  fsyncSync,
7	  mkdirSync,
8	  readFileSync,
9	  writeFileSync,
10	  truncateSync,
11	  renameSync,
12	  rmSync,
13	  existsSync,
14	  readdirSync,
15	  statSync,
16	} from 'node:fs';
17	import path from 'node:path';
18	import { randomUUID } from 'node:crypto';
19	
20	const LOG_NAME = 'bus.jsonl';
21	const LOG_TMP_NAME = 'bus.log.tmp';
22	const SNAPSHOT_NAME = 'bus.snapshot.json';
23	const SNAPSHOT_TMP_NAME = 'bus.snapshot.tmp';
24	// Cross-process coordination files.
25	//  - bus.lock is a short-lived mutex directory (O_EXCL mkdir) held only while
26	//    a process actually mutates the directory, so bytes from two writers can
27	//    never interleave in a file.
28	//  - bus.owner.json is the write lease. It carries the epoch credential that
29	//    increments on every takeover and the sessions holding the current lease;
30	//    a heartbeat keeps it fresh while a process is alive.
31	//  - bus.epoch is the durable high-water mark for epochs, so an epoch can
32	//    never be reused across takeovers/restarts.
33	const LOCK_NAME = 'bus.lock';
34	const OWNER_NAME = 'bus.owner.json';
35	const EPOCH_NAME = 'bus.epoch';
36	// Per-session heartbeat files (bus.hb.<sessionId>) are written WITHOUT the
37	// mutex, so a process blocked waiting for the lock still proves it is alive
38	// and is never wrongly taken over. A session whose newest heartbeat is older
39	// than LEASE_MS is dead and may be replaced.
40	const HB_PREFIX = 'bus.hb.';
41	const HB_TMP_PREFIX = 'bus.hb.tmp.';
42	// Every temp file a write uses is session-scoped under one of these
43	// prefixes, so two writers never clobber each other's tmp; stale leftovers
44	// from a crashed holder are swept under the lock on the next open.
45	//
46	// Commit pipeline files. Writers stage publish/publishBatch requests into
47	// bus.q.<token>.json WITHOUT holding the mutex (after sync validation and
48	// reservation), then take the lock and drain the whole staging area: every
49	// staged request from every process is merged into ONE bracketed commit
50	// group, so one flush covers the combined set. The drain's plan (seqs,
51	// dedup, per-request quota, stats) is persisted in a decision file before
52	// the group is flushed, and per-request outcomes (acks / rejection) are
53	// written to bus.r.<token>.json so a request drained by another process —
54	// or after a crash mid-flush — is adopted with the same first
55	// acknowledgement. A chunked group's torn tail is healed against the
56	// decision: missing chunks make the whole group invisible.
57	const QUEUE_PREFIX = 'bus.q.';
58	const DECISION_PREFIX = 'bus.c.';
59	const RESULT_PREFIX = 'bus.r.';
60	const TMP_PREFIXES = [
61	  'bus.owner.tmp.',
62	  'bus.epoch.tmp.',
63	  HB_TMP_PREFIX,
64	  'bus.snapshot.tmp.',
65	  'bus.snapshot.mirror.tmp.',
66	  'bus.log.tmp.',
67	  'bus.log.reset.tmp.',
68	  'bus.q.tmp.',
69	  'bus.c.tmp.',
70	  'bus.r.tmp.',
71	];
72	const envLease = Number(process.env.BUS_LEASE_MS);
73	const LEASE_MS = envLease > 0 ? envLease : 3000;
74	const envRenew = Number(process.env.BUS_RENEW_MS);
75	const RENEW_MS = envRenew > 0 ? envRenew : Math.min(250, Math.floor(LEASE_MS / 10));
76	// Test/diagnostic seams (not part of the public surface), read live so
77	// they can be toggled per test:
78	//  - BUS_DRAIN_DELAY_MS: hold the mutex at the drain entrance (heartbeat
79	//    kept fresh) so concurrently staged requests deterministically join
80	//    the same commit group.
81	//  - BUS_DRAIN_STALL_MS: after the first flush chunk block WITHOUT
82	//    refreshing the heartbeat, reproducing a holder seized mid group.
83	//  - BUS_FLUSH_FAIL_AT: fail the flush once this many group bytes are down.
84	const seamNumber = (name) => Number(process.env[name]) || 0;
85	// A mutex directory untouched for longer than this, whose owning session's
86	// heartbeat is also stale, belongs to a process that died mid-job; the next
87	// waiter breaks it.
88	const LOCK_STALE_MS = LEASE_MS;
89	const LOCK_SPIN_MS = 5;
90	const LOCK_WAIT_MS = 15000;
91	// Best-effort stats()/usage() scan: never block long behind a write job.
92	const VIEW_WAIT_MS = 100;
93	
94	// The log is a chain of segment files: the active `bus.jsonl` plus finalized
95	// `bus.<index>.jsonl` segments. Index order is oldest first; an index is
96	// never reused within the lifetime of a directory.
97	const SEGMENT_RE = /^bus\.(\d+)\.jsonl$/;
98	const segmentName = (index) => `bus.${String(index).padStart(10, '0')}.jsonl`;
99	// Multi-writer snapshots live in gen/epoch-scoped files so a preempted
100	// holder completing a stale compaction can never clobber a newer snapshot by
101	// renaming over a fixed name. The unscoped bus.snapshot.json stays readable
102	// as the legacy/canonical form (older buses and hand-crafted layouts).
103	const SNAPSHOT_SCOPED_RE = /^bus\.snapshot\.g(\d+)\.e(\d+)\.json$/;
104	const snapshotScopedName = (gen, epoch) => `bus.snapshot.g${gen}.e${epoch}.json`;
105	
106	// Pipeline file name patterns (constructors live in createBus, where the
107	// session id exists): token = pid + '-' + session tag + '-' + nonce, so two
108	// processes never collide and a process never reuses a crashed token.
109	const QUEUE_RE = /^bus\.q\.(.+)\.json$/;
110	const DECISION_RE = /^bus\.c\.(.+)\.json$/;
111	const RESULT_RE = /^bus\.r\.(.+)\.json$/;
112	
113	const sleepSync = (ms) => {
114	  const slot = new Int32Array(new SharedArrayBuffer(4));
115	  Atomics.wait(slot, 0, 0, Math.max(1, ms));
116	};
117	
118	/**
119	 * Validate that `value` survives a compact JSON.stringify unchanged.
120	 * JSON silently drops undefined / functions and turns non-finite numbers
121	 * into null; the spec rejects those along with BigInt and circular
122	 * references as TypeError.
123	 */
124	function assertJsonSafe(value, stack = new Set()) {
125	  if (typeof value === 'bigint') {
126	    throw new TypeError('record contains a BigInt');
127	  }
128	  if (typeof value === 'function') {
129	    throw new TypeError('record contains a function');
130	  }
131	  if (typeof value === 'undefined') {
132	    throw new TypeError('record contains undefined');
133	  }
134	  if (typeof value === 'number' && !Number.isFinite(value)) {
135	    throw new TypeError('record contains a non-finite number');
136	  }
137	  if (value !== null && typeof value === 'object') {
138	    // Unbox boxed primitives (e.g. new Number(NaN)) before recursing.
139	    if (value instanceof Number || value instanceof String || value instanceof Boolean) {
140	      assertJsonSafe(value.valueOf(), stack);
141	      return;
142	    }
143	    if (stack.has(value)) {
144	      throw new TypeError('record contains a circular reference');
145	    }
146	    stack.add(value);
147	    if (Array.isArray(value)) {
148	      for (const item of value) assertJsonSafe(item, stack);
149	    } else {
150	      for (const key of Object.keys(value)) assertJsonSafe(value[key], stack);
151	    }
152	    stack.delete(value);
153	  }
154	}
155	
156	/**
157	 * Split a jsonl buffer into parsed entries. `durable` is the offset just
158	 * past the final newline; anything beyond it is a torn trailing write.
159	 */
160	function parseLog(raw) {
161	  const entries = [];
162	  let start = 0;
163	  for (let i = 0; i < raw.length; i++) {
164	    if (raw[i] === 0x0a) {
165	      if (i > start) entries.push(JSON.parse(raw.toString('utf8', start, i)));
166	      start = i + 1;
167	    }
168	  }
169	  return { entries, durable: start };
170	}
171	
172	// Read just the first line of the active log as a structural fingerprint.
173	// Compaction/truncate always replace that line with a marker, so comparing
174	// it detects a rename-based reset even when the filesystem reuses an inode
175	// number. Capped at a small prefix: only the head bytes are needed.
176	const readHeadSync = (filePath) => {
177	  let fd;
178	  try {
179	    fd = openSync(filePath, 'r');
180	  } catch {
181	    return null;
182	  }
183	  try {
184	    const buf = Buffer.allocUnsafe(4096);
185	    const n = readSync(fd, buf, 0, buf.length, 0);
186	    if (!Number.isInteger(n) || n <= 0) return '';
187	    const got = buf.subarray(0, n);
188	    const nl = got.indexOf(0x0a);
189	    return got.subarray(0, nl < 0 ? got.length : nl).toString('utf8');
190	  } catch {
191	    return null;
192	  } finally {
193	    try {
194	      closeSync(fd);
195	    } catch {
196	      // Already closed.
197	    }
198	  }
199	};
200	
201	// Finalized segments present in the directory, oldest first.
202	const listSegments = (dir) => {
203	  const out = [];
204	  for (const name of readdirSync(dir)) {
205	    const match = SEGMENT_RE.exec(name);
206	    if (match) out.push({ index: Number(match[1]), path: path.join(dir, name) });
207	  }
208	  out.sort((a, b) => a.index - b.index);
209	  return out;
210	};
211	
212	/**
213	 * Extract the committed, non-stale entries from a raw log buffer, using the
214	 * same bracket/fence rules as scanDirectory's recovery walk but without
215	 * touching any state: the incremental tail reader applies the result onto
216	 * the cached merged view. Returns { units, watermark, closed, structural }:
217	 * `closed` is false when the buffer ends inside an uncommitted batch
218	 * bracket (a crash mid group), in which case the caller heals with a full
219	 * scan; `structural` is set when a truncate/compact marker or a fence was
220	 * seen, which also forces a full rescan.
221	 */
222	function committedUnits(raw, startWatermark) {
223	  const units = [];
224	  let watermark = startWatermark;
225	  let lineStart = 0;
226	  let group = null;
227	  let structural = false;
228	  const stale = (entry) =>
229	    entry !== null && typeof entry.g === 'number' && entry.g < watermark;
230	  for (let i = 0; i < raw.length; i++) {
231	    if (raw[i] !== 0x0a) continue;
232	    const entry = i > lineStart ? JSON.parse(raw.toString('utf8', lineStart, i)) : null;
233	    if (entry && entry.t === 'f') {
234	      if (typeof entry.g === 'number' && entry.g > watermark) watermark = entry.g;
235	      structural = true;
236	      group = null;
237	    } else if (group !== null) {
238	      if (stale(entry)) {
239	        // A preempted holder's bytes never close or enter the group.
240	      } else if (entry && entry.t === 'bk' && entry.id === group.id) {
241	        for (const member of group.entries) units.push(member);
242	        group = null;
243	      } else if (entry && entry.t === 'b') {
244	        group = { id: entry.id, entries: [] };
245	      } else if (entry) {
246	        group.entries.push(entry);
247	      }
248	    } else if (entry && entry.t === 'b') {
249	      if (!stale(entry)) group = { id: entry.id, entries: [] };
250	    } else if (entry) {
251	      if (entry.t === 't' || entry.t === 'c') {
252	        structural = true;
253	      } else if (!stale(entry)) {
254	        units.push(entry);
255	      }
256	    }
257	    lineStart = i + 1;
258	  }
259	  // Bytes past the final newline are a torn trailing write (a crash mid
260	  // line). They are never parsed; the caller treats them like an open
261	  // bracket — heal before appending.
262	  const torn = lineStart < raw.length;
263	  return { units, watermark, closed: group === null, structural, torn };
264	}
265	
266	
267	// First complete line of a log file, or null when there is none.
268	const firstEntry = (filePath) => {
269	  const raw = readFileSync(filePath);
270	  const nl = raw.indexOf(0x0a);
271	  if (nl <= 0) return null;
272	  try {
273	    return JSON.parse(raw.toString('utf8', 0, nl));
274	  } catch {
275	    return null;
276	  }
277	};
278	
279	// Highest message seq in a segment file; null when it carries no messages.
280	const segmentMaxSeq = (filePath) => {
281	  const { entries } = parseLog(readFileSync(filePath));
282	  let max = null;
283	  for (const entry of entries) {
284	    if (entry.t === 'm' && (max === null || entry.seq > max)) max = entry.seq;
285	  }
286	  return max;
287	};
288	
289	/**
290	 * Non-destructive view of the whole directory. Applies exactly the same
291	 * recovery rules the single-process opener used (snapshot anchor, truncate
292	 * checkpoint marker, committed batch brackets only, torn tails severed) but
293	 * changes nothing on disk: callers run it under the cross-process lock and
294	 * act on its result. Because every surviving fact is read from the shared
295	 * files each time, dedup keys, positions, quota occupancy and cumulative
296	 * stats are one merged state across every writer.
297	 */
298	function scanDirectory(dir) {
299	  const logPath = path.join(dir, LOG_NAME);
300	  const snapshotPath = path.join(dir, SNAPSHOT_NAME);
301	
302	  const state = {
303	    seq: 0,
304	    bytes: 0,
305	    published: 0,
306	    replayed: 0,
307	    horizon: 0,
308	    dedup: new Map(),
309	    positions: new Map(),
310	  };
311	  let snapshotGen = 0;
312	  let foldedSeq = 0;
313	  let baseMessages = [];
314	  // Surviving messages visible above the checkpoint/horizon floors, in
315	  // ascending order (retained pre-anchor segments plus the committed
316	  // suffix).
317	  const live = [];
318	  // Every accepted log-side message (same filtering as recovery), used to
319	  // recompute retained occupancy without re-parsing files.
320	  const accepted = [];
321	  // Highest epoch fenced off in this directory: complete log bytes carrying
322	  // a smaller epoch that physically follow a fence line are bytes a
323	  // preempted holder wrote after losing ownership — never mixed into state.
324	  let fenceEpoch = 0;
325	  let nextSegmentIndex = 1;
326	
327	  // Snapshot candidates are resolved AFTER the ordered log and its fence
328	  // watermark are known (see below): an anchor-less snapshot from a holder a
329	  // higher fence displaced must never become a reset basis.
330	
331	  // A line is stale only when it carries an explicit epoch stamp below the
332	  // fence watermark. Lines written before multi-writer support have no
333	  // stamp and were committed by a legitimate holder, so they always count.
334	  const epochOf = (entry) => (entry !== null && typeof entry.g === 'number' ? entry.g : 0);
335	  const isStale = (entry, watermark) =>
336	    entry !== null && typeof entry.g === 'number' && entry.g < watermark;
337	
338	  const applyEntry = (entry, watermark) => {
339	    // A line stamped with an epoch below the current fence watermark was
340	    // written by a holder that had already lost ownership: it never mixes
341	    // into counters, positions, dedup or the visible log.
342	    if (isStale(entry, watermark)) return;
343	    if (entry.t === 'm') {
344	      // At/below the horizon the message was discarded by truncation; only
345	      // its cumulative counters (carried by the marker) survive.
346	      if (entry.seq <= state.horizon) return;
347	      state.seq = entry.seq;
348	      state.bytes += entry.bytes;
349	      state.published += 1;
350	      if (typeof entry.d === 'string') {
351	        state.dedup.set(entry.d, { id: entry.id, seq: entry.seq });
352	      }
353	      const msg = { seq: entry.seq, id: entry.id, record: entry.record };
354	      live.push(msg);
355	      accepted.push(msg);
356	    } else if (entry.t === 's') {
357	      state.replayed += entry.n;
358	    } else if (entry.t === 'p') {
359	      state.positions.set(entry.name, entry.pos);
360	    }
361	  };
362	
363	  // A truncate marker is an absolute checkpoint: the cumulative counters,
364	  // positions and dedup table it carries replace whatever earlier segments
365	  // established, so recovery can start from the newest marker and ignore
366	  // everything before it.
367	  const applyMarker = (entry) => {
368	    state.seq = entry.seq;
369	    state.bytes = entry.bytes;
370	    state.published = entry.published;
371	    state.replayed = entry.replayed;
372	    state.horizon = entry.horizon;
373	    state.positions.clear();
374	    for (const [name, pos] of Object.entries(entry.positions)) state.positions.set(name, pos);
375	    state.dedup.clear();
376	    for (const [key, value] of entry.dedup) state.dedup.set(key, value);
377	  };
378	
379	  const markerLine = (gen) => JSON.stringify({ t: 'c', gen }) + '\n';
380	
381	  // Replay complete log lines and apply only the committed, non-fenced
382	  // prefix. A batch is bracketed by {t:'b',id} .. entries .. {t:'bk',id}: a
383	  // begin without its matching commit (crash mid-write, overtaken by a newer
384	  // begin, or a fence line) is severed wholesale and none of its entries
385	  // take effect. A {t:'f',e} fence raises the epoch watermark: every later
386	  // line stamped with a smaller epoch is a preempted holder's byte and is
387	  // ignored even when physically complete. The watermark lives in
388	  // `fenceState` so it carries across files in segment order. Returns the
389	  // byte offset just past the last retainable line, so torn tails and
390	  // current-epoch uncommitted tails can be truncated while fenced leftovers
391	  // stay put (logically invisible) rather than reshaping the file.
392	  // `startWatermark` is the fence watermark established by every earlier
393	  // file in segment order. It is positional, not global: history committed
394	  // before the fence line (even by the same older epoch) is legitimate and
395	  // must be retained; only bytes physically after a fence with a smaller
396	  // stamp are discarded.
397	  const recoverLog = (raw, startWatermark) => {
398	    let watermark = startWatermark;
399	    let lineStart = 0;
400	    let retainableEnd = 0;
401	    let group = null;
402	    for (let i = 0; i < raw.length; i++) {
403	      if (raw[i] !== 0x0a) continue;
404	      const entry = i > lineStart ? JSON.parse(raw.toString('utf8', lineStart, i)) : null;
405	      const completeEnd = i + 1;
406	      if (entry && entry.t === 'f') {
407	        if (epochOf(entry) > watermark) watermark = epochOf(entry);
408	        fenceEpoch = Math.max(fenceEpoch, watermark);
409	        // The fence aborts any batch a preempted holder left open.
410	        group = null;
411	        retainableEnd = completeEnd;
412	      } else if (group !== null) {
413	        if (isStale(entry, watermark)) {
414	          // Preempted holder's bytes (even a matching-looking commit) never
415	          // close or apply the current group.
416	          retainableEnd = completeEnd;
417	        } else if (entry && entry.t === 'bk' && entry.id === group.id) {
418	          for (const e of group.entries) applyEntry(e, watermark);
419	          group = null;
420	          retainableEnd = completeEnd;
421	        } else if (entry && entry.t === 'b') {
422	          // The previous group never committed; start tracking the new one.
423	          group = { id: entry.id, entries: [], beginOffset: lineStart };
424	          retainableEnd = completeEnd;
425	        } else if (entry) {
426	          group.entries.push(entry);
427	        }
428	      } else if (entry && entry.t === 'b') {
429	        if (isStale(entry, watermark)) {
430	          // A stale uncommitted group: ignore it but keep its bytes.
431	          retainableEnd = completeEnd;
432	        } else {
433	          group = { id: entry.id, entries: [], beginOffset: lineStart };
434	        }
435	      } else {
436	        if (entry) {
437	          if (entry.t === 't') applyMarker(entry);
438	          else applyEntry(entry, watermark);
439	        }
440	        retainableEnd = completeEnd;
441	      }
442	      lineStart = completeEnd;
443	    }
444	    // A current-epoch group still open at EOF is a crash/seizure mid-batch:
445	    // its bytes must be severed, so the retainable prefix ends before the
446	    // begin line (anything stale past a fence was already ignored above).
447	    if (group !== null) {
448	      return Math.min(retainableEnd, group.beginOffset);
449	    }
450	    return retainableEnd;
451	  };
452	
453	  const segments = listSegments(dir);
454	  for (const seg of segments) {
455	    if (seg.index >= nextSegmentIndex) nextSegmentIndex = seg.index + 1;
456	  }
457	  // The ordered log is every finalized segment (oldest first) followed by
458	  // the active log file.
459	  const ordered = segments.map((seg) => seg.path);
460	  if (existsSync(logPath)) ordered.push(logPath);
461	
462	  // Pending physical repairs discovered by the scan; applied by healLocked()
463	  // while the cross-process lock is held.
464	  const tails = [];
465	  const removable = [];
466	  let reset = false;
467	
468	  // Fences raise the epoch watermark in log order. Walk every file first so
469	  // each file is scanned with the watermark as of its own position and the
470	  // global maximum is known before choosing a snapshot: a fence in an
471	  // earlier segment governs later files, never earlier ones.
472	  const watermarkAtStart = [];
473	  let globalFence = 0;
474	  {
475	    let wm = 0;
476	    for (let i = 0; i < ordered.length; i++) {
477	      watermarkAtStart.push(wm);
478	      const { entries } = parseLog(readFileSync(ordered[i]));
479	      for (const entry of entries) {
480	        if (entry.t === 'f' && epochOf(entry) > wm) wm = epochOf(entry);
481	      }
482	    }
483	    globalFence = wm;
484	  }
485	
486	  // Choose the newest snapshot among the canonical file and the
487	  // gen/epoch-scoped files. Generation is primary; within one generation a
488	  // higher epoch wins, so a preempted holder finishing a stale compaction
489	  // after a takeover can never eclipse the current owner's snapshot.
490	  const snapshotCandidates = [];
491	  if (existsSync(snapshotPath)) snapshotCandidates.push({ file: snapshotPath, gen: -1, epoch: 0 });
492	  for (const name of readdirSync(dir)) {
493	    const m = SNAPSHOT_SCOPED_RE.exec(name);
494	    if (m) {
495	      snapshotCandidates.push({
496	        file: path.join(dir, name),
497	        gen: Number(m[1]),
498	        epoch: Number(m[2]),
499	      });
500	    }
501	  }
502	  snapshotCandidates.sort((a, b) =>
503	    a.gen !== b.gen ? a.gen - b.gen : a.epoch - b.epoch,
504	  );
505	
506	  const loadSnapshot = (cand) => {
507	    const snap = JSON.parse(readFileSync(cand.file, 'utf8'));
508	    snapshotGen = snap.gen;
509	    fenceEpoch = Math.max(globalFence, typeof snap.e === 'number' ? snap.e : 0);
510	    state.seq = snap.seq;
511	    state.bytes = snap.bytes;
512	    state.published = snap.published;
513	    state.replayed = snap.replayed;
514	    state.horizon = snap.horizon ?? 0;
515	    foldedSeq = snap.seq;
516	    state.dedup.clear();
517	    state.positions.clear();
518	    for (const [key, value] of snap.dedup) state.dedup.set(key, value);
519	    for (const [name, pos] of Object.entries(snap.positions)) state.positions.set(name, pos);
520	    baseMessages = snap.messages;
521	  };
522	
523	  // Resolve the usable snapshot newest-first. A candidate is usable when its
524	  // compaction completed (an anchor marker for its generation exists in the
525	  // log) or, when anchor-less, its writer's epoch is at least the current
526	  // fence watermark — i.e. the snapshot landed in its own legitimate
527	  // crash window rather than being finished by a holder a later takeover
528	  // displaced. Anchor-less candidates below the watermark are orphans: they
529	  // are removed and resolution falls back to the next-newest snapshot (whose
530	  // anchored history is still intact).
531	  let chosenSnapshot = null;
532	  let chosenHasAnchor = false;
533	  for (let k = snapshotCandidates.length - 1; k >= 0; k--) {
534	    const cand = snapshotCandidates[k];
535	    const snap = JSON.parse(readFileSync(cand.file, 'utf8'));
536	    let hasAnchor = false;
537	    for (const filePath of ordered) {
538	      const first = firstEntry(filePath);
539	      if (first && (first.t === 'c' || first.t === 't') && first.gen === snap.gen) {
