102	test('multi-process: two live processes interleave publishes with continuous seqs', async () => {
103	  const dir = await freshDir();
104	  const a = new Worker(dir);
105	  const b = new Worker(dir);
106	
107	  // Deterministic alternation first.
108	  const seqs = [];
109	  for (let i = 0; i < 3; i++) {
110	    seqs.push((await a.call('publish', { record: { w: 'a', i } })).seq);
111	    seqs.push((await b.call('publish', { record: { w: 'b', i } })).seq);
112	  }
113	  assert.deepEqual(seqs, [1, 2, 3, 4, 5, 6]);
114	
115	  // Then a truly concurrent burst from both processes.
116	  const burst = [];
117	  for (let i = 0; i < 20; i++) {
118	    burst.push(a.call('publish', { record: { w: 'a', n: i } }));
119	    burst.push(b.call('publish', { record: { w: 'b', n: i } }));
120	  }
121	  const acks = await Promise.all(burst);
122	  const allSeqs = acks.map((x) => x.seq).sort((x, y) => x - y);
123	  assert.deepEqual(allSeqs, Array.from({ length: 40 }, (_, i) => i + 7));
124	
125	  // Concurrent batches from both processes.
126	  const [ba, bb] = await Promise.all([
127	    a.call('publishBatch', { records: [{ g: 1 }, { g: 2 }, { g: 3 }] }),
128	    b.call('publishBatch', { records: [{ g: 4 }, { g: 5 }] }),
129	  ]);
130	  const batchSeqs = ba.concat(bb).map((x) => x.seq).sort((x, y) => x - y);
131	  assert.deepEqual(batchSeqs, [47, 48, 49, 50, 51]);
132	
133	  await a.call('close');
134	  await b.call('close');
135	
136	  // A fresh opener sees one continuous, gapless, duplication-free log.
137	  const bus = createBus({ path: dir });
138	  const got = await bus.replay(0);
139	  assert.equal(got.length, 51);
140	  assert.deepEqual(
141	    got.map((m) => m.seq),
142	    Array.from({ length: 51 }, (_, i) => i + 1),
143	  );
144	  assert.equal(bus.stats().published, 51);
145	  assert.equal(bus.stats().seq, 51);
146	  await bus.close();
147	});
