import { spawn } from 'node:child_process';
import { rmSync, readFileSync } from 'node:fs';
import { createBus } from '/mnt/c/claude_gsb/cla06/solverA/task013/src/index.js';

const WORKER = '/mnt/c/claude_gsb/cla06/solverA/task013/helpers/worker.mjs';
const dir = '/tmp/rr-xproc';
rmSync(dir, { recursive: true, force: true });

class Worker {
  constructor(env = {}) {
    this.child = spawn(process.execPath, [WORKER], {
      stdio: ['pipe', 'pipe', 'inherit'],
      env: { ...process.env, ...env, BUS_DIR: dir },
    });
    this.nextId = 1;
    this.pending = new Map();
    this.buf = '';
    this.child.stdout.setEncoding('utf8');
    this.child.stdout.on('data', (c) => {
      this.buf += c;
      let i;
      while ((i = this.buf.indexOf('\n')) >= 0) {
        const line = this.buf.slice(0, i);
        this.buf = this.buf.slice(i + 1);
        if (!line) continue;
        const m = JSON.parse(line);
        const s = this.pending.get(m.id);
        if (s) { this.pending.delete(m.id); s(m); }
      }
    });
  }
  call(op, params = {}) {
    const id = this.nextId++;
    return new Promise((res) => {
      this.pending.set(id, res);
      this.child.stdin.write(JSON.stringify({ id, op, ...params }) + '\n');
    });
  }
  kill() { try { this.child.kill('SIGKILL'); } catch {} }
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// 1) Cross-process merge: A holds the drain entrance briefly; B stages mid-hold.
const a = new Worker({ BUS_DRAIN_DELAY_MS: '250' });
