let lines = readFileSync(dir + '/bus.jsonl', 'utf8').trim().split('\n').map((l) => JSON.parse(l));
console.log('groups', lines.filter((e) => e.t === 'b').length, 'msgs', lines.filter((e) => e.t === 'm').map((e) => e.seq));

// 2) Lock-free readRange from THIS process while a worker holds the drain.
