const p = c.call('publish', { record: { w: 'c' } });
await sleep(150);
const bus = createBus({ path: dir });
const t0 = Date.now();
const got = bus.readRange(1, 10);
console.log('readRange during remote drain', got.map((m) => m.seq), 'in', Date.now() - t0, 'ms');
