  assert.equal(entries.filter((e) => e.t === 'bk').length, 1);
  assert.deepEqual(
    entries.filter((e) => e.t === 'm').map((e) => e.seq),
    [1, 2, 3],
  );
  await a.call('close');
  await b.call('close');
});

